	if err != nil || len(files) == 0 {
		f.Fatalf("no embedded fixture to seed the fuzz target with (err %v)", err)
	}
	for _, path := range files {
		data, err := os.ReadFile(path)
		if err != nil {
			f.Fatal(err)
		}
		f.Add(data)
	}
	two := synthValid + "###\n" + synthRequest[1:] + synthResponse
